<?php
declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('GET');accounts_endpoint(function():array{$db=production_db();$id=(int)($_GET['id']??0);$base="SELECT r.*,b.name current_bank_name FROM qbook_customer_receipts r JOIN qbook_bank_accounts b ON b.id=r.bank_account_id";if($id<=0){$rows=$db->query($base." WHERE r.status='POSTED' ORDER BY r.receipt_date DESC,r.id DESC")->fetchAll();foreach($rows as&$r)$r['reference']=billing_ref('RECEIPT',$r['reference_no']);unset($r);return['payments'=>$rows];}$s=$db->prepare($base." WHERE r.id=? AND r.status='POSTED'");$s->execute([$id]);$r=$s->fetch();if(!$r)accounts_fail('POSTED_CLIENT_PAYMENT_NOT_FOUND',404);$r['reference']=billing_ref('RECEIPT',$r['reference_no']);$a=$db->prepare("SELECT a.*,i.reference_no invoice_reference_no,GROUP_CONCAT(DISTINCT NULLIF(l.project_snapshot,'') ORDER BY l.project_snapshot SEPARATOR ' • ') project_names,t.code wht_code,w.rate_snapshot,w.calculation_base_snapshot,w.calculation_base_amount,w.suggested_amount,w.accepted_amount,w.override_reason,w.certificate_status FROM qbook_customer_receipt_allocations a JOIN qbook_invoices i ON i.id=a.invoice_id LEFT JOIN qbook_invoice_lines l ON l.invoice_id=i.id LEFT JOIN qbook_customer_receipt_allocation_wht w ON w.receipt_allocation_id=a.id LEFT JOIN qbook_tax_codes t ON t.id=w.tax_code_id WHERE a.receipt_id=? GROUP BY a.id ORDER BY a.id");$a->execute([$id]);$alloc=$a->fetchAll();$cashApplied=$wht=0;foreach($alloc as&$x){$x['invoice_reference']=billing_ref('INVOICE',$x['invoice_reference_no']);$cashApplied+=accounts_money_minor($x['cash_amount'],false);$wht+=accounts_money_minor($x['wht_amount'],false);}unset($x);$cash=accounts_money_minor($r['cash_amount'],false);return['payment'=>$r,'allocations'=>$alloc,'summary'=>['cash_received'=>accounts_minor_decimal($cash),'cash_applied'=>accounts_minor_decimal($cashApplied),'wht_deducted'=>accounts_minor_decimal($wht),'invoice_settlement'=>accounts_minor_decimal($cashApplied+$wht),'unallocated_credit'=>accounts_minor_decimal($cash-$cashApplied)]];});
